            var eligible=root.TipOutEmployeeWeights.eligible(rule,present,edit.included===true || (rule.distribution==='hours' && edit.hours!==undefined && h>0));
            var weightMap=(rec.employeeWeights||{})[f.role]||{};
            var employeeWeight=edit.employeeWeight!==undefined?edit.employeeWeight:Object.prototype.hasOwnProperty.call(weightMap,f.name)?weightMap[f.name]:1;
            if(employeeWeight==null||employeeWeight===''||!Number.isFinite(Number(employeeWeight))||Number(employeeWeight)<0||Number(employeeWeight)>1000000)throw new Error('员工权重无效');
