        returnEmployeeId: returnEmployeeId || '',
        employeeSummaryRole: employeeSummaryFilters.role || '',
        employeeSummaryStatus: employeeSummaryFilters.statuses[0] || '',
        employeeSummaryScope: employeeSummaryFilters.employeeScope,
