      var datePayoutStatusField = document.getElementById('datePayoutStatusField');
      var dateSortField = document.getElementById('dateSortField');
      var employeeFilters = document.getElementById('employeeSummaryFilters');
      var dateMetrics = document.getElementById('dateSummaryMetrics');
