      if (dateBusinessStatusField) dateBusinessStatusField.hidden = employeeActive;
      if (datePayoutStatusField) datePayoutStatusField.hidden = employeeActive;
      if (dateSortField) dateSortField.hidden = employeeActive;
      if (employeeFilters) employeeFilters.hidden = !employeeActive;
      if (dateMetrics) dateMetrics.hidden = employeeActive;
