      var seen = {};
      (plainItems || []).forEach(function(nm) {
        all.forEach(function(k) {
          var p = String(k).split(MENU_KEY_SEP);
          if (p[p.length - 1] === nm && !seen[k]) { seen[k] = 1; out.push(k); }
        });
      });
      return out;
