      var gMs = card.querySelector('.menu-cascade-group');
      var cMs = card.querySelector('.menu-cascade-category');
      var iMs = card.querySelector('.menu-cascade-item');
      if (!plMs || !gMs || !cMs || !iMs) return;
      var plArr = Array.isArray(stored.productLine) ? stored.productLine.slice() : (stored.productLine ? [stored.productLine] : []);
      var gArr = Array.isArray(stored.menuGroup) ? stored.menuGroup.slice() : [];
      var catArr = Array.isArray(stored.category) ? stored.category.slice() : (stored.category ? [stored.category] : []);
