      if (cond.hours && (cond.hours.start || cond.hours.end)) parts.push('订单时间段: ' + (cond.hours.start || '') + '-' + (cond.hours.end || ''));
      if (Array.isArray(cond.shift) && cond.shift.length) parts.push('班次: ' + formatShiftSelectionForDisplay(cond.shift));
      if (Array.isArray(cond.weekdays) && cond.weekdays.length) parts.push('周期: ' + formatWeekdaysCondDisplay(cond.weekdays));
      return parts.join(' | ');
